&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will often take the role as the game-developer advocate when working with the platform teams, or the role as the platform-team advocate when working with game developers.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a&amp;nbsp;senior position at the core of PlayStation GPU technology&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;with an&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;unusual&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;degree of&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;influence&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;on&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;future of&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;console&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;graphics&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;-programming&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&amp;nbsp;ATG is granted a high degree of trust and autonomy in shaping the graphics software stack and we are looking for people&amp;nbsp;who are passionate about carrying this forward.&amp;nbsp;You will not be spending your time in committee meetings&amp;nbsp;or writing endless proposals, this is very much an engineering role where your primary role is to&amp;nbsp;determine&amp;nbsp;what needs to be implemented, how best to implement it and to&amp;nbsp;then sit down,&amp;nbsp;code, debug. We believe that this practical focus is crucial in building up the skill, experience, and insight&amp;nbsp;required&amp;nbsp;to make the large-scale and long-term decisions we have been entrusted with.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What we are looking for&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience and interest in low-level graphics architecture and engineering.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
