&lt;p&gt;&lt;strong&gt;Mission Brief&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This is an exciting opportunity to join Isar Aerospace in a key role.&lt;/p&gt;
&lt;p&gt;You will be&lt;span class=&quot;TextRun SCXW52956684 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW52956684 BCX8&quot;&gt;&amp;nbsp;responsible for proper financial accounting, the preparation of financial statements, and the ongoing optimization and digitization of accounting processes in an international SAP S/4HANA environment.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW52956684 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;strong&gt;Your Role in Our Space Mission:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Record payment transactions and bank activities: Ensure timely and accurate bank reconciliations&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Support cost control and invoice approvals: Collaborate with managers to control expenses and handle invoice approvals&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Maintain accurate asset records: Perform asset accounting, reconcile balance sheets, and manage intercompany accounts&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Assistance with the preparation of monthly, quarterly and annual financial statements under HGB and Local GAAP&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Responsibility for the general ledger, provisions, accruals, and balance sheet reconciliations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Participation in SAP rollouts, system optimizations, and finance projects&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Conducting intercompany reconciliations and providing support to international subsidiaries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Close coordination with Operations and Controlling on project- and performance-related accounting matters&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Close collaboration with Group Accounting for Reportings&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Collaboration with IT, Controlling, Tax, and international shared-service organizations&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:525,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
