&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: arial, helvetica, sans-serif;&quot;&gt;Minimum 25 days annual leave and volunteer days&lt;/span&gt;&lt;/li&gt;
