&lt;p&gt;&lt;span class=&quot;TextRun SCXW75588371 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;We are&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;seeking&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;&amp;nbsp;an experienced and strategic Director of EMEA Marketing to lead the marketing function across Europe.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW75588371 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;This role owns the EMEA marketing function end-to-end, partnering with global marketing leadership on shared standards while holding full accountability for regional strategy and results, reporting&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW75588371 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;into our GM of EMEA&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;.&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW75588371 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW75588371 BCX8&quot;&gt;The Director will manage a marketing team, while working cross-functionally with global directors of content, product marketing, and events. The Director will reconcile competing priorities across sales, product, corporate leadership, and global functional heads as the senior marketing voice for EMEA.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Responsibilities:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Set and own EMEA marketing strategy, contributing directly to how the global function evaluates and refines its overall approach across regions&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
