&lt;ul type=&quot;disc&quot;&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;Analyse und Optimierung von&amp;nbsp;&lt;strong&gt;End-to-End Advisory-, Portfolio- und Investment-Prozessen&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Übersetzung fachlicher Anforderungen in&amp;nbsp;&lt;strong&gt;Business Requirements, BRDs, User Stories und funktionale Konzepte&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;Konzeption von Lösungen in den Bereichen&amp;nbsp;&lt;strong&gt;Advisory Offering &amp;amp; Pricing, Suitability, Portfolio Construction, Execution und Reporting&lt;/strong&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Definition fachlicher Anforderungen für&amp;nbsp;&lt;strong&gt;Advisory-Plattformen, Aladdin Wealth, Investment-Plattformen und Wertpapierprozesse&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Unterstützung bei Plattform-Konfiguration, Integrationsdesign, Vendor-Steuerung sowie MVP-Umsetzung&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Enge Zusammenarbeit mit Business, IT, Architektur und Operations während Design, Implementierung, Testing und Rollout&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Dein Profil&lt;/strong&gt;&lt;/p&gt;
&lt;ul type=&quot;disc&quot;&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot; data-olk-copy-source=&quot;MessageBody&quot;&gt;Mehrjährige Erfahrung als&amp;nbsp;&lt;strong&gt;Business Analyst&lt;/strong&gt;&amp;nbsp;im&amp;nbsp;&lt;strong&gt;Wealth Management, Private Banking oder Capital Markets Umfeld&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Fundiertes Verständnis von&amp;nbsp;&lt;strong&gt;Investment Advisory, Wertpapiergeschäft, Portfolio Management und digitalen Wealth-Plattformen&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Erfahrung mit&amp;nbsp;&lt;strong&gt;Aladdin Wealth&lt;/strong&gt;&amp;nbsp;oder vergleichbaren Advisory- und Investment-Plattformen&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;Kenntnisse in&amp;nbsp;&lt;strong&gt;Suitability, Portfolio Construction, Order Management und dem Investment Lifecycle&lt;/strong&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Erfahrung in der Übersetzung fachlicher Anforderungen in funktionale und technische Spezifikationen&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Strukturierte, analytische Arbeitsweise sowie ausgeprägte Kommunikations- und Stakeholder-Management-Fähigkeiten&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;Fließende Deutsch- und Englischkenntnisse&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Nice to have&lt;/strong&gt;&lt;/p&gt;
&lt;ul type=&quot;disc&quot;&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;Erfahrung mit&amp;nbsp;&lt;strong&gt;Digital Advisory&lt;/strong&gt;&amp;nbsp;und&amp;nbsp;&lt;strong&gt;Discretionary Portfolio Management (DPM)&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;Kenntnisse regulatorischer Anforderungen (z. B.&amp;nbsp;&lt;strong&gt;MiFID II&lt;/strong&gt;, Suitability, Investment Advisory)&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;Erfahrung mit agilen Delivery-Methoden&lt;/li&gt;
&lt;li class=&quot;x_MsoNormal&quot;&gt;&lt;span lang=&quot;DE&quot;&gt;Erfahrung in internationalen Transformationsprogrammen sowie in der Zusammenarbeit mit Software-Vendoren&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
